curves = result.curves()
curves.index = (curves.index - curves.index[0]).total_seconds()

fig, (ax_u, ax_w) = plt.subplots(1, 2, figsize=(11, 4))
ax_u.plot(curves.index, curves["NETWORK__BUS____4_TN_U_value"], color=PALETTE[0])
